CREATE TABLE "PlayProfile" ("userId" TEXT NOT NULL PRIMARY KEY,"xp" INTEGER NOT NULL DEFAULT 0,"sessions" INTEGER NOT NULL DEFAULT 0,"points" INTEGER NOT NULL DEFAULT 0,"publicName" BOOLEAN NOT NULL DEFAULT false,"suspended" BOOLEAN NOT NULL DEFAULT false,"moderationReason" TEXT NOT NULL DEFAULT '',"lastActivity" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "PlayGame" ("slug" TEXT NOT NULL PRIMARY KEY,"status" TEXT NOT NULL DEFAULT 'ENABLED',"version" INTEGER NOT NULL DEFAULT 1,"configuration" TEXT NOT NULL DEFAULT '{}',"updatedAt" DATETIME NOT NULL);
CREATE TABLE "PlaySession" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"gameSlug" TEXT NOT NULL,"configVersion" INTEGER NOT NULL,"configuration" TEXT NOT NULL,"seed" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"score" INTEGER NOT NULL DEFAULT 0,"xp" INTEGER NOT NULL DEFAULT 0,"frames" INTEGER NOT NULL DEFAULT 0,"replay" TEXT NOT NULL DEFAULT '[]',"evidenceHash" TEXT,"rejectionReason" TEXT,"questions" TEXT NOT NULL DEFAULT '[]',"answered" INTEGER NOT NULL DEFAULT 0,"questionAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" DATETIME NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" DATETIME,FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("gameSlug") REFERENCES "PlayGame"("slug") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "PlayXpEntry" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"amount" INTEGER NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("sessionId") REFERENCES "PlaySession"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "PlayAchievementGrant" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"code" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("userId") REFERENCES "PlayProfile"("userId") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "PlayQuestion" ("id" TEXT NOT NULL PRIMARY KEY,"language" TEXT NOT NULL,"prompt" TEXT NOT NULL,"options" TEXT NOT NULL,"answer" INTEGER NOT NULL,"explanation" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"difficulty" TEXT NOT NULL DEFAULT 'NORMAL',"fingerprint" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "PlaySession_userId_createdAt_idx" ON "PlaySession"("userId","createdAt");
CREATE INDEX "PlaySession_gameSlug_status_completedAt_idx" ON "PlaySession"("gameSlug","status","completedAt");
CREATE UNIQUE INDEX "PlayXpEntry_sessionId_key" ON "PlayXpEntry"("sessionId");
CREATE INDEX "PlayXpEntry_userId_createdAt_idx" ON "PlayXpEntry"("userId","createdAt");
CREATE UNIQUE INDEX "PlayAchievementGrant_userId_code_key" ON "PlayAchievementGrant"("userId","code");
CREATE UNIQUE INDEX "PlayQuestion_fingerprint_key" ON "PlayQuestion"("fingerprint");
CREATE INDEX "PlayQuestion_language_status_idx" ON "PlayQuestion"("language","status");
ALTER TABLE "PlaySession" ADD COLUMN "tournamentId" TEXT;
CREATE INDEX "PlaySession_tournamentId_userId_status_idx" ON "PlaySession"("tournamentId","userId","status");
CREATE TABLE "PlayTournament" ("id" TEXT NOT NULL PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"gameSlug" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"seed" INTEGER NOT NULL,"startsAt" DATETIME NOT NULL,"endsAt" DATETIME NOT NULL,"maxAttempts" INTEGER NOT NULL DEFAULT 3,"maxParticipants" INTEGER NOT NULL DEFAULT 1000,"rewardTitle" TEXT NOT NULL DEFAULT '',"terms" TEXT NOT NULL,"results" TEXT NOT NULL DEFAULT '[]',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PlayTournamentEntry" ("id" TEXT NOT NULL PRIMARY KEY,"tournamentId" TEXT NOT NULL,"userId" TEXT NOT NULL,"joinedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("tournamentId") REFERENCES "PlayTournament"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("userId") REFERENCES "PlayProfile"("userId") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PlayTournamentEntry_tournamentId_userId_key" ON "PlayTournamentEntry"("tournamentId","userId");
CREATE TABLE "PlayRewardGrant" ("id" TEXT NOT NULL PRIMARY KEY,"tournamentId" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'APPROVED',"deliveryNote" TEXT NOT NULL DEFAULT '',"approvedBy" TEXT NOT NULL,"fulfilledAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("tournamentId") REFERENCES "PlayTournament"("id") ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY ("userId") REFERENCES "PlayProfile"("userId") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PlayRewardGrant_tournamentId_userId_key" ON "PlayRewardGrant"("tournamentId","userId");
ALTER TABLE "PlayTournament" ADD COLUMN "configuration" TEXT NOT NULL DEFAULT '{}';
ALTER TABLE "PlayTournament" ADD COLUMN "configVersion" INTEGER NOT NULL DEFAULT 1;
